"""Seal text snapshot, refresh ONLY metadata of pending active inputs, write note.
Does not rerun tests/physics or read raw artifacts for hashes.
"""
from pathlib import Path
import ast,datetime,hashlib,json
P=Path(__file__).resolve().parents[1];WT=P.parents[2]
S=Path(r'F:\RMPOLAR-RL\mod4v1_lqr_mpc_robust_20261102')
def sha(b):return hashlib.sha256(b).hexdigest()
def load(p):return json.loads(p.read_text(encoding='utf-8'))
def dump(p,x):assert not p.exists(),str(p);p.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def main():
    assert not (P/'SEAL.json').exists()
    m=load(P/'manifest.json');old_pending=(P/'PHASE2_PENDING.json').read_bytes();q=json.loads(old_pending);included={x['source_relative']:x for x in m['entries']}
    pending=[];cache=[];changes=[]
    for p in S.rglob('*'):
        if not p.is_file() or p.is_symlink():continue
        rel=p.relative_to(S).as_posix();st=p.stat()
        row={'path':str(p),'source_relative':rel,'bytes':st.st_size,'mtime_ns':st.st_mtime_ns,'mtime_utc':datetime.datetime.fromtimestamp(st.st_mtime,datetime.timezone.utc).isoformat()}
        if rel in included:
            e=included[rel]
            if (e['bytes'],e['mtime_ns'])!=(st.st_size,st.st_mtime_ns):changes.append(dict(row,captured_original_sha256=e['original_sha256'],reason='source_changed_after_capture_phase2'))
        elif '__pycache__' in p.parts:cache.append(row)
        else:pending.append(dict(row,reason='not_in_sealed_phase1_whitelist_or_post_cutoff_active_future'))
    backup=P/'PHASE2_PENDING_initial.json';dump(backup,json.loads(old_pending))
    q.update(observed_files=pending,captured_then_changed=changes,pending_metadata_refreshed_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),late_admissions_removed_from_pending=['SPR_AUDIT/portable_core_v2_kinematics','reports/STATE14_SCHEMA_ERRATUM.md'],runtime_cache_metadata_only_count=len(cache))
    (P/'PHASE2_PENDING.json').write_text(json.dumps(q,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
    copied=[x for x in m['entries'] if x.get('archive_path')];checks=[]
    for e in copied:
        raw=(WT/e['archive_path']).read_bytes();digest=sha(raw);assert digest==e['archive_sha256']
        if e['redactions']==0:assert digest==e['original_sha256']
        checks.append({'archive_path':e['archive_path'],'bytes':len(raw),'sha256':digest,'source_capture_sha256':e['original_sha256']})
    registry=load(P/'CASE_AND_ATTEMPT_REGISTRY.json');assert len(registry['case_results'])==30
    for rel in ['TASK_SCOPE.md','PROPOSED_ACCEPTANCE_V1.md','nominal_gain_v1.json','reports/STATE14_SCHEMA_ERRATUM.md','SPR_AUDIT/portable_core_v2_kinematics/VALIDATION.json']:
        assert rel in included,rel+' missing required source'
    assert not any('/r04' in x['source_relative'].lower() or '/r05' in x['source_relative'].lower() or 'portable_mpc_qp_v1' in x['source_relative'] for x in m['entries'])
    summary={**m['summary'],'copied_text_files_final':len(copied),'copied_text_bytes_final':sum(x['archive_bytes'] for x in copied),'pending_observed_files_at_seal':len(pending),'source_changes_after_capture':len(changes),'raw_SHA_unresolved_not_rehashed':sum(x['capture_kind'].startswith('index_only') and x['original_sha256'] is None for x in m['entries'])}
    qa={'status':'SEALED_TEXT_CAPTURE_BYTE_HASH_MATCH','summary':summary,'copied_text_hash_checks':checks,'source_change_flags':changes,'raw_rehash_count':0,'new_simulation_steps':0,'new_test_runs':0,'secret_redactions_total':sum(x['redactions'] for x in copied),'raw_originals_remain_at_source':True,'main_original_worktree_not_a_write_target':True,'credential_scripts_and_weights_not_committed':True}
    dump(P/'FINAL_CAPTURE_QA.json',qa)
    note='''# MOD4v1 robust traditional-control phase1 — sealed evidence archive\n\nThis is an authorized diagnostic Git archival stage, not a new training/physics episode.\n\n## Scope and observed results\n\nMain source cutoff: 2026-11-02T12:37:47+08:00. The source task is F:/RMPOLAR-RL/mod4v1_lqr_mpc_robust_20261102. Sealed MODEL_AUDIT, SPR_AUDIT, DATA_DIAGNOSTIC, r00 source snapshots, nominal gain, R00/R01/R02/R03 configs/batches/results/ERRORs and reports are preserved. Parent explicitly admitted sealed portable_core_v2_kinematics and the exact append-only STATE14_SCHEMA_ERRATUM before this snapshot seal. Other R04/R05/future reports are not admitted.\n\nAll30existing case result IDs are independently indexed in CASE_AND_ATTEMPT_REGISTRY.json with their actual stored completion, stop, metric and provisional gate fields. Completion is not acceptance; gates from different revisions are not silently unified. R03 nominal forward_gated stored tail vx=2.004531m/s/RMSE=.0170256, spin_gated yaw=12.592855rad/s/RMSE=.0753744. These are nominal physical screens, not independent holdout, robust full-course graduation, 270mm step, realboard, or newly validated MPC skill. The overall parent Goal remains active.\n\n## Failures and corrections preserved\n\nThe original9pass/1fail jerk endpoint unit event, subsequent reported10pass fix, diagnostic three-MCI and superseded preliminary model, missing true tire mesh correction, nv0static-fixture AssertionError, first C build -Werror/misleading-indentation failure and historical sources/logs, R00time-alignment erratum, and empty-new-worktree-index setup problem/repair remain separate evidence. C1README's knee labels are not edited: STATE14_SCHEMA_ERRATUM appends the correction that state14[4/6] are crank-minus-hip delta and11/13 their derivatives, not passive linkage knee. C1/C2 math/source/receipts retain original bytes.\n\n## Capture and raw originals\n\nmanifest.json maps each original text byte SHA256 to its archive byte SHA256 and complete/redacted/index-only status. The original initial manifest and pending list are retained before the precise late admission. All copied text bytes match their archived hashes; source originals were never modified. Trace JSONL, raw/bin, STL/USD/ZIP/EXE/OBJ, NPZ/weights and large originals are indexed only using metadata and already-existing producer digest claims. No raw original was reopened to calculate a hash for archival. Unknown or conflicting current hashes are explicitly unknown, never fabricated. Producer-claim hashes are not falsely described as fresh verification.\n\n## Git isolation and verification\n\nOnly F:/RMPOLAR-RL/repo-lqr-robust on branch mod4v1-lqr-mpc-robust is a write target. Its empty initial index was repaired index-only, and19physically absent selected policy/helper files were materialized without overwrites. The other original worktree remains on its expert branch and is an active other session: its HEAD/index changes across separate read probes are measured facts with no process attribution, not a false claim of byte-identical state. No reset/restore/add/checkout write was sent to that original worktree.\n\nUse the unmodified archive_tools/record_experiment.py to create unique diagnostic id mod4v1-robust-traditional-phase1 and annotated tag trial-20261102-mod4v1-robust-traditional-phase1. A narrow in-process adapter only replaces its single long git-add operand list by this exact owned directory plus the generated record. Before commit, staged path set must equal every selected archive file plus that record, no D/foreign paths, and staged blob bytes must match selected hashes. The helper is not edited. Push only the owned branch and new tag with explicit refspecs, then compare remote main/tag object/peeled commit.\n\n## Pending, not task completion\n\nR04(all files even if parent reports32/32complete), R05+, active portable_mpc_qp_v1, all post-cutoff or later-modified sources/reports and post-commit synchronization receipts remain PHASE2_PENDING. Do not stop any CPU/GPU task, import hardware SDKs, run SSH, replay units/physics, change the physical model, or touch canonical budgets for archival. Tool receipt after commit may be emitted without recursively manufacturing trials; if persisted as a report, it is explicitly phase2pending.\n'''
    (P/'NOTE.md').write_text(note,encoding='utf-8')
    readme=f'''# MOD4v1 robust traditional-control PHASE1\n\n**Sealed source evidence through R03; overall control Goal stays active.**\n\n- [{len(copied)} complete byte-hashed text copies](<manifest.json>), {sum(x['archive_bytes'] for x in copied):,}bytes; no redactions.\n- [{len(registry['case_results'])} independent existing case IDs plus historical failures](<CASE_AND_ATTEMPT_REGISTRY.json>).\n- [{summary['raw_index_only_files']} in-task raw originals indexed only](<manifest.json>); {summary['raw_known_producer_sha']} bound existing producer hashes, {summary['raw_SHA_unresolved_not_rehashed']} unknown/current-unbound; {summary['external_authority_index_entries']} explicit external authority references indexed. No raw rehash.\n- [{len(pending)} observed pending files at seal](<PHASE2_PENDING.json>), including all R04/R05 and active MPC; future changes and sync receipt remain pending.\n- [Final text-byte QA](<FINAL_CAPTURE_QA.json>), [initial capture counters](<CAPTURE_SUMMARY.json>), [worktree setup failure/repair](<WORKTREE_SETUP_REPAIR.json>).\n- [Append-only state14 schema correction](<snapshot/reports/STATE14_SCHEMA_ERRATUM.md>) preserves original C1source/README/manifest bytes.\n- [Full stage note](<NOTE.md>), [late admission evidence](<LATE_ADMISSION_STATE14.json>).\n\n## Physical claims, not inflated\n\nR03nominal forward_gated:2.004531m/s, trackingRMSE.0170256; spin_gated:12.592855rad/s, trackingRMSE.0753744. These remain stored nominal screens, not independent holdout/fullDRgraduation,270mm,realboard or new-MPCqualification. Original provisional gate claims/failed runs are preserved individually, not changed to pass.\n\nC1host18152checks/0fail and C2kinematics2761checks/0fail are algebra fixtures, not robot episodes or ARM/board tests. Model/IMU diagnostics and their original failed fixtures are not physical skill graduation.\n\n## Capture boundary\n\nMain cutoff2026-11-02T12:37:47+08; actual main capture{m['capture_started_utc']}–{m['capture_finished_utc']}. Parent explicitly admitted already-sealed portable_core_v2_kinematics and one exact STATE14erratum before seal. No other newer report or R04/R05result was admitted. manifest_capture_initial.json and PHASE2_PENDING_initial.json preserve the initial versions; CAPTURE_SUMMARY is initial, manifest/FINAL_CAPTURE_QA give final counts.\n\nFiles in snapshot retain original content and provenance paths; binary originals stay at source. This archive stage has0new physics steps,0unit reruns, no model/hardware changes, no credential/SSH actions.\n'''
    (P/'README.md').write_text(readme,encoding='utf-8')
    for p in (P/'tools').glob('*.py'):ast.parse(p.read_text(encoding='utf-8'))
    dump(P/'SEAL.json',{'sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'R00_R03plus_parent_sealed_C2and_exact_state14erratum','manifest_sha256':sha((P/'manifest.json').read_bytes()),'final_capture_qa_sha256':sha((P/'FINAL_CAPTURE_QA.json').read_bytes()),'pending_sha256':sha((P/'PHASE2_PENDING.json').read_bytes()),'snapshot_text_files':len(copied),'snapshot_source_files_unchanged_since_capture_count':len(copied)-len(changes),'raw_rehash_count':0,'new_physics_steps':0,'new_unit_runs':0,'no_more_source_admissions_in_phase1':True,'post_commit_receipt':'Emit tool output or persist in source Task as phase2pending; do not recurse receipt commits.'})
    print(json.dumps({'sealed':True,'summary':summary,'manifest_sha256':sha((P/'manifest.json').read_bytes()),'seal_sha256':sha((P/'SEAL.json').read_bytes())},indent=2))
